import sys

def longest_palindromic_prefix(s):
    n = len(s)
    rev_s = s[::-1]
    combined = s + '#' + rev_s
    lps = [0] * len(combined)
    for i in range(1, len(combined)):
        j = lps[i - 1]
        while j > 0 and combined[i] != combined[j]:
            j = lps[j - 1]
        if combined[i] == combined[j]:
            j += 1
        lps[i] = j
    return s[:lps[-1]]

def longest_palindromic_suffix(s):
    return longest_palindromic_prefix(s[::-1])[::-1]

def prefix_frequencies(s):
    freq = {}
    for i in range(1, len(s) + 1):
        prefix = s[:i]
        if prefix in freq:
            freq[prefix] += 1
        else:
            freq[prefix] = 1
    return [freq[s[:i]] for i in range(1, len(s) + 1)]

s = sys.stdin.read().strip()
lp = longest_palindromic_prefix(s)
ls = longest_palindromic_suffix(s)
omeric_string = ls + lp
prefix_freq = prefix_frequencies(omeric_string)

print(omeric_string)
print(' '.join(map(str, prefix_freq)))
